// Isolated candidate: capture a held request, acknowledge next cycle,
// then expose it downstream. Common reset is the only legal abort.
reg ack_q;
reg valid_q;

wire capture_intent = rst_ni && req_i && !valid_q;
assign gnt_o = rst_ni && ack_q;
assign req_o = rst_ni && valid_q && !ack_q;

always @(posedge clk_i or negedge rst_ni)
  if (!rst_ni) ack_q <= 1'b0;
  else ack_q <= capture_intent;

